// ?setWeaponLock@Rva001EBA30WeaponSet@@QAE_NW4WeaponSlotType@@W4WeaponLockType@@@Z
// partial score=0.9 date=2026-09-10
// ?setWeaponLock@Rva001EBA30WeaponSet@@QAE_NW4WeaponSlotType@@W4WeaponLockType@@@Z
// BFME helper at retail 0x001EBA30, full boundary 214 bytes through ret 8.
// The Object::setWeaponLock wrapper at 0x001CEA50 reaches this body through
// ILT 0x0004705F with the WeaponSet subobject at Object+0x264, establishing
// the thiscall slot/lock ABI.  This focused TU keeps the BFME four-slot and
// owner-id layout out of the ZH WeaponSet.cpp header.
//
// New codegen lever over reverse/attempts/0x001eba30.cpp: keep explicit
// `self` and `object` views alive across the owner lookup.  Retail keeps the
// WeaponSet receiver in EDI and the looked-up Object in ESI; the prior complete
// bank had the same bytes in the opposite register convention.
// cl: /O2 /GR- /DNDEBUG /DWIN32 /MD /EHsc-

typedef int Int;
typedef bool Bool;

enum ObjectID
{
	INVALID_ID = 0,
	FORCE_OBJECTID_TO_LONG_SIZE = 0x7ffffff
};

enum WeaponSlotType
{
	PRIMARY_WEAPON = 0,
	SECONDARY_WEAPON = 1,
	TERTIARY_WEAPON = 2
};

enum WeaponLockType
{
	NOT_LOCKED = 0,
	LOCKED_TEMPORARILY = 1,
	LOCKED_PERMANENTLY = 2
};

class Weapon;
class Object;
class WeaponTemplateSet;

class GameLogic
{
public:
	Object *findObjectByID(ObjectID id);
};

extern GameLogic *TheGameLogic;

template <size_t NUMBITS>
class BitFlags
{
public:
	enum BogusInitType
	{
		kInit = 0
	};

	BitFlags(BogusInitType, Int idx1, Int idx2, Int idx3);

private:
	unsigned int m_bits[(NUMBITS + 31) / 32];
};

typedef BitFlags<304> ModelConditionFlags;

class Object
{
public:
	void clearModelConditionFlags(const ModelConditionFlags &clr);
	void notifyModelConditionChanged();

	unsigned char m_pad_00[0x120];
	unsigned int m_conditionWord4;
};

class Rva001EBA30WeaponSet
{
public:
	Bool setWeaponLock(WeaponSlotType weaponSlot, WeaponLockType lockType);

public:
	void *m_vtable;
	const WeaponTemplateSet *m_curWeaponTemplateSet;
	Weapon *m_weapons[4];
	WeaponSlotType m_curWeapon;
	WeaponLockType m_curWeaponLockedStatus;
	unsigned int m_filledWeaponSlotMask;
	Int m_totalAntiMask;
	unsigned int m_totalDamageTypeMask;
	Bool m_hasPitchLimit;
	Bool m_hasDamageWeapon;
	unsigned char m_pad_2e[0x34 - 0x2e];
	ObjectID m_objectId;
};

static __forceinline Bool rva001EBA30_setWeaponLock(
	WeaponSlotType weaponSlot, WeaponLockType lockType,
	Rva001EBA30WeaponSet *self)
{
	register Rva001EBA30WeaponSet *receiver = self;
	register const Object *object = TheGameLogic->findObjectByID(receiver->m_objectId);

	if (lockType != NOT_LOCKED)
	{
		Weapon *weapon = receiver->m_weapons[weaponSlot];
		if (weapon != 0)
		{
			WeaponLockType permanent = LOCKED_PERMANENTLY;
			if (lockType == permanent)
			{
				receiver->m_curWeaponLockedStatus = permanent;
				receiver->m_curWeapon = weaponSlot;
			}
			else if (lockType == LOCKED_TEMPORARILY
				&& receiver->m_curWeaponLockedStatus != permanent)
			{
				receiver->m_curWeaponLockedStatus = LOCKED_TEMPORARILY;
				receiver->m_curWeapon = weaponSlot;
			}

			if (object)
				const_cast<Object *>(object)->clearModelConditionFlags(
					ModelConditionFlags(ModelConditionFlags::kInit, 0x88, 0x89, 0x8A));

			unsigned int mask;
			switch (receiver->m_curWeapon - PRIMARY_WEAPON)
			{
			case 2:
				if (object)
				{
					mask = 0x400;
					goto applyMask;
				}
				break;
			case 1:
				if (object)
				{
					mask = 0x200;
					goto applyMask;
				}
				break;
			case 0:
				if (object)
				{
					mask = 0x100;
					goto applyMask;
				}
				break;
			}
			return true;

		applyMask:
			unsigned int current = object->m_conditionWord4;
			if ((current & mask) == 0)
			{
				const_cast<Object *>(object)->m_conditionWord4 = current | mask;
				const_cast<Object *>(object)->notifyModelConditionChanged();
			}
			return true;
		}
	}
	return false;
}

Bool Rva001EBA30WeaponSet::setWeaponLock(WeaponSlotType weaponSlot,
	WeaponLockType lockType)
{
	return rva001EBA30_setWeaponLock(weaponSlot, lockType, this);
}
